 * such that `a[i] === b[j]` for every pair and the list is a longest common
 * subsequence of `a` and `b`.
 *
 * Ties are broken by walking both sequences from the start: take a match
 * whenever the two current lines are equal, and otherwise advance the side
 * whose remaining subsequence is at least as long as the other's, preferring
 * to advance `a` (the base, when this is used for a base/side comparison)
 * when the two options tie.
 */
export function lcsMatches(a, b) {
  const n = a.length
  const m = b.length
  // dp[i][j] holds the LCS length of a[i:] and b[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const row = dp[i]
    const nextRow = dp[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      if (a[i] === b[j]) {
        row[j] = nextRow[j + 1] + 1
      } else {
        const skipA = nextRow[j]
        const skipB = row[j + 1]
        row[j] = skipA >= skipB ? skipA : skipB
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
